10	
11	#if __CCE_AICORE__ == 220 && defined(__DAV_C220_VEC__)
12	
13	#include "kernel_operator.h"
14	#include <pto/pto-inst.hpp>
15	
16	using namespace pto;
17	
18	constexpr uint32_t BLOCK_DIM = 20;                     // number of vector cores(AIVs)
19	constexpr unsigned BLOCK_ROWS = 20;                    // number of AIVs in rows
20	constexpr unsigned BLOCK_COLS = 1;                     // number of AIVs in cols
21	constexpr uint32_t BUFFER_NUM = 2;                     // ping-pong buffer
22	constexpr unsigned UB_SIZE = 0x30000;                  // 192KB UB of A2A3
23	constexpr unsigned X_PING = 0x0;                       // ping address of input x in UB buffer
24	constexpr unsigned X_PONG = (X_PING + 0x8000 + 0x100); // pong address of input x in UB buffer
25	constexpr unsigned Y_PING = 0x10000;                   // ping address of input y in UB buffer
26	constexpr unsigned Y_PONG = (Y_PING + 0x8000 + 0x100); // pong address of input y in UB buffer
27	constexpr unsigned Z_PING = 0x20000;                   // ping address of output z in UB buffer
28	constexpr unsigned Z_PONG = (Z_PING + 0x8000 + 0x100); // pong address of output z in UB buffer
29	constexpr unsigned MAX_TILE_SIZE = (0x10000 - 0x100);  // Maximum tile size
30	constexpr uint32_t tileNum = 2;                        // tile number on one vector core
31	
32	template <typename T, unsigned tileRows, unsigned tileCols>
33	AICORE void runTAdd(__gm__ T* z, __gm__ T* x, __gm__ T* y, uint32_t totalLength)
34	{
35	    set_mask_norm();
36	    set_vector_mask(-1, -1);
37	    static_assert(BLOCK_ROWS * BLOCK_COLS == BLOCK_DIM, "Wrong block tilling!");
38	    // inter-vector cores block tiling
39	    constexpr unsigned bTileRows = tileRows / BLOCK_ROWS;
40	    constexpr unsigned bTileCols = tileCols / BLOCK_COLS;
41	    static_assert(bTileRows * bTileCols * sizeof(T) <= MAX_TILE_SIZE, "UB buffer overflow.");
42	
43	    // inner-vector core block tiling
44	    constexpr unsigned tileSRows = bTileRows;
45	    constexpr unsigned tileSCols = bTileCols / tileNum / BUFFER_NUM;
46	    // define GlobalData on global memory with shape and stride
47	    using ShapeDim5 = pto::Shape<1, 1, 1, tileSRows, tileSCols>;
48	    using StridDim5 = pto::Stride<1, 1, 1, tileCols, 1>;
49	    using GlobalData = pto::GlobalTensor<T, ShapeDim5, StridDim5>;
50	    GlobalData xGlobal(x);
51	    GlobalData yGlobal(y);
52	    GlobalData zGlobal(z);
53	
54	    // define TileData on UB buffer with static shape and dynamic mask
55	    using TileData = Tile<TileType::Vec, T, tileSRows, tileSCols, BLayout::RowMajor, -1, -1>;
56	    unsigned bLength = totalLength / AscendC::GetBlockNum();
57	    // valid mask(vRows, vCols) of each tile
58	    unsigned vRows = tileRows / AscendC::GetBlockNum();
59	    unsigned vCols = bLength / tileNum / BUFFER_NUM;
60	    // define ping-pong buffer for related tiles
61	    TileData xTiles[BUFFER_NUM] = {TileData(vRows, vCols), TileData(vRows, vCols)};
62	    TileData yTiles[BUFFER_NUM] = {TileData(vRows, vCols), TileData(vRows, vCols)};
63	    TileData zTiles[BUFFER_NUM] = {TileData(vRows, vCols), TileData(vRows, vCols)};
64	
65	    // assign the UB address for each tile
66	    TASSIGN(xTiles[0], X_PING);
67	    TASSIGN(xTiles[1], X_PONG);
68	    TASSIGN(yTiles[0], Y_PING);
69	    TASSIGN(yTiles[1], Y_PONG);
70	    TASSIGN(zTiles[0], Z_PING);
71	    TASSIGN(zTiles[1], Z_PONG);
72	    // total number of loops of one vector core
73	    int32_t loopCount = tileNum * BUFFER_NUM;
74	    // address offset between vector cores
75	    unsigned offset = block_idx * bTileRows * bTileCols;
76	    int8_t pingpong_flag = 0; // ping pong pipeline flag
77	
78	    // synchronization operations between hardware pipelines
79	    set_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
80	    set_flag(PIPE_V, PIPE_MTE2, EVENT_ID1);
81	    set_flag(PIPE_MTE3, PIPE_V, EVENT_ID0);
82	    set_flag(PIPE_MTE3, PIPE_V, EVENT_ID1);
83	    for (uint32_t i = 0; i < loopCount; i++) {
84	        unsigned iterOffset = offset + i * tileSRows * tileSCols;
85	        // update address of GlobalData
86	        TASSIGN(xGlobal, x + iterOffset);
87	        TASSIGN(yGlobal, y + iterOffset);
88	        TASSIGN(zGlobal, z + iterOffset);
89	
90	        wait_flag(PIPE_V, PIPE_MTE2, (event_t)(pingpong_flag));
91	        // load data from global memory to UB buffer
92	        TLOAD(xTiles[pingpong_flag], xGlobal);
93	        TLOAD(yTiles[pingpong_flag], yGlobal);
94	
95	        set_flag(PIPE_MTE2, PIPE_V, (event_t)(pingpong_flag));
96	        wait_flag(PIPE_MTE2, PIPE_V, (event_t)(pingpong_flag));
97	
98	        wait_flag(PIPE_MTE3, PIPE_V, (event_t)(pingpong_flag));
99	        // perform elementwise addition by vector core
100	        TADD(zTiles[pingpong_flag], xTiles[pingpong_flag], yTiles[pingpong_flag]);
101	        set_flag(PIPE_V, PIPE_MTE2, (event_t)(pingpong_flag));
102	
103	        set_flag(PIPE_V, PIPE_MTE3, (event_t)(pingpong_flag));
104	        wait_flag(PIPE_V, PIPE_MTE3, (event_t)(pingpong_flag));
105	        // store data from UB buffer to global memory
106	        TSTORE(zGlobal, zTiles[pingpong_flag]);
107	        set_flag(PIPE_MTE3, PIPE_V, (event_t)(pingpong_flag));
108	        pingpong_flag = (pingpong_flag == 0) ? 1 : 0;
109	    }
110	    wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID0);
111	    wait_flag(PIPE_V, PIPE_MTE2, EVENT_ID1);
112	    wait_flag(PIPE_MTE3, PIPE_V, EVENT_ID0);
113	    wait_flag(PIPE_MTE3, PIPE_V, EVENT_ID1);
114	    TASSIGN(zGlobal, z);
115	    z = zGlobal.data();
116	}
117	
118	// kernel entry
119	extern "C" __global__ AICORE void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z, uint32_t totalLength)
120	{
121	    // Define the tile size
122	    constexpr unsigned tileRows = 20;
123	    constexpr unsigned tileCols = 2048;
124	    // main kernel, totalLength is dynamic input
125	    runTAdd<half, tileRows, tileCols>((__gm__ half*)z, (__gm__ half*)x, (__gm__ half*)y, totalLength);
126	}
127	
128	#endif
