1	# Auto Mode Examples
2	
3	## Scope
4	
5	This document shows examples of kernels written in auto mode versus in manual mode.
6	
7	
8	## TADD
9	
10	```cpp
11	
12	#include <pto/pto-inst.hpp>
13	#include <pto/common/constants.hpp>
14	
15	using namespace pto;
16	
17	AICORE void runTAdd(__gm__ float __out__ *out, __gm__ float __in__ *src0, __gm__ float __in__ *src1) {
18	    using DynShapeDim5 = Shape<1, 1, 1, 64, 64>;
19	    using DynStridDim5 = Stride<1, 1, 1, 64, 1>;
20	    using GlobalData = GlobalTensor<float, DynShapeDim5, DynStridDim5>;
21	    using TileData = Tile<TileType::Vec, float, 64, 64, BLayout::RowMajor, 64, 64>;
22	    TileData src0Tile(64, 64);
23	    TileData src1Tile(64, 64);
24	    TileData dstTile(64, 64);
25	
26	    GlobalData src0Global(src0);
27	    GlobalData src1Global(src1);
28	    GlobalData dstGlobal(out);
29	
30	    TLOAD(src0Tile, src0Global);
31	    TLOAD(src1Tile, src1Global);
32	
33	    TADD(dstTile, src0Tile, src1Tile);
34	
35	    TSTORE(dstGlobal, dstTile);
36	}
37	
38	```
39	
40	Whereas in manual mode, it would look like this:
41	
42	```cpp
43	
44	#include <pto/pto-inst.hpp>
45	#include <pto/common/constants.hpp>
46	
47	using namespace pto;
48	
49	AICORE void runTAdd(__gm__ float __out__ *out, __gm__ float __in__ *src0, __gm__ float __in__ *src1) {
50	    using DynShapeDim5 = Shape<1, 1, 1, 64, 64>;
51	    using DynStridDim5 = Stride<1, 1, 1, 64, 1>;
52	    using GlobalData = GlobalTensor<float, DynShapeDim5, DynStridDim5>;
53	    using TileData = Tile<TileType::Vec, float, 64, 64, BLayout::RowMajor, 64, 64>;
54	    TileData src0Tile(64, 64);
55	    TileData src1Tile(64, 64);
56	    TileData dstTile(64, 64);
57	
58	    /* TAssign only in manual mode */
59	    TASSIGN(src0Tile, 0x0);
60	    TASSIGN(src1Tile, 0x10000);
61	    TASSIGN(dstTile, 0x20000);
62	
63	    GlobalData src0Global(src0);
64	    GlobalData src1Global(src1);
65	    GlobalData dstGlobal(out);
66	
67	    /* event model only in manual mode */
68	    Event<Op::TLOAD, Op::TADD> event0;
69	    Event<Op::TADD, Op::TSTORE_VEC> event1;
70	
71	    TLOAD(src0Tile, src0Global);
72	    event0 = TLOAD(src1Tile, src1Global);
73	    event1 = TADD(dstTile, src0Tile, src1Tile, event0);
74	    TSTORE(dstGlobal, dstTile, event1);
75	}
76	
77	```
78	
79	## TMATMUL
80	
81	```cpp
82	
83	#include <pto/pto-inst.hpp>
84	#include <pto/common/constants.hpp>
85	
86	using namespace pto;
87	
88	template <typename cType, typename aType, typename bType, typename fbType, typename l0cType, int M, int K, int N,
89	          int ValidM, int ValidK, int ValidN>
90	__global__ AICORE void runTMatMul(__gm__ cType *out, __gm__ aType *src0, __gm__ bType *src1, __gm__ fbType *src2)
91	{
92	    using GlobalDataSrc0 = GlobalTensor<aType, pto::Shape<1, 1, 1, ValidM, ValidK>,
93	                                        pto::Stride<ValidM * ValidK, ValidM * ValidK, ValidM * ValidK, ValidK, 1>>;
94	    using GlobalDataSrc1 = GlobalTensor<bType, pto::Shape<1, 1, 1, ValidK, ValidN>,
95	                                        pto::Stride<ValidK * ValidN, ValidK * ValidN, ValidK * ValidN, ValidN, 1>>;
96	    using GlobalDataSrc2 =
97	        GlobalTensor<fbType, pto::Shape<1, 1, 1, 1, ValidN>, pto::Stride<ValidN, ValidN, ValidN, ValidN, 1>>;
98	    using GlobalDataOut = GlobalTensor<cType, pto::Shape<1, 1, 1, ValidM, ValidN>,
99	                                       pto::Stride<ValidM * ValidN, ValidM * ValidN, ValidM * ValidN, ValidN, 1>>;
100	
101	    GlobalDataSrc0 src0Global(src0);
102	    GlobalDataSrc1 src1Global(src1);
103	    GlobalDataSrc2 src2Global(src2);
104	    GlobalDataOut dstGlobal(out);
105	
106	    using TileMatAData = Tile<TileType::Mat, aType, M, K, BLayout::ColMajor, ValidM, ValidK, SLayout::RowMajor, 512>;
107	    using TileMatBData = Tile<TileType::Mat, bType, K, N, BLayout::ColMajor, ValidK, ValidN, SLayout::RowMajor, 512>;
108	    using TileMatFbData = Tile<TileType::Mat, fbType, 1, N, BLayout::RowMajor, 1, ValidN, SLayout::NoneBox>;
109	
110	    using LeftTile = TileLeft<aType, M, K, ValidM, ValidK>;
111	    using RightTile = TileRight<bType, K, N, ValidK, ValidN>;
112	    using AccTile = TileAcc<l0cType, M, N, ValidM, ValidN>;
113	
114	    using FbTile = Tile<TileType::Scaling, fbType, 1, N, BLayout::RowMajor, 1, ValidN, SLayout::NoneBox>;
115	
116	    TileMatAData aMatTile;
117	    TileMatBData bMatTile;
118	    TileMatFbData fbMatTile;
119	
120	    LeftTile aTile;
121	    RightTile bTile;
122	    AccTile cTile;
123	    FbTile fbTile;
124	
125	    TLOAD(aMatTile, src0Global);
126	    TLOAD(bMatTile, src1Global);
127	    TLOAD(fbMatTile, src2Global);
128	
129	    /**************************TMOV & TMATMUL**************************/
130	    TMOV(aTile, aMatTile);
131	    TMOV(bTile, bMatTile);
132	    TMATMUL(cTile, aTile, bTile);
133	    TMOV(fbTile, fbMatTile);
134	
135	    /********************************TSTORE****************************/
136	    TSTORE_FP<AccTile, GlobalDataOut, FbTile>(dstGlobal, cTile, fbTile);
137	}
138	```
139	
140	Versus in manual mode:
141	
142	```cpp
143	
144	#include <pto/pto-inst.hpp>
145	#include <pto/common/constants.hpp>
146	
147	using namespace pto;
148	
